if (useSlerp) {
    // Upstream passes 1 - weight to offset the pinned hlsl++ slerp's
    // reversed endpoints; that slerp still omits one spherical
    // coefficient. Interpolate the shortest arc directly by weight.
    const hlslpp::quaternion target = float(dot(a.rotation, b.rotation)) > 0.0f
        ? b.rotation : -b.rotation;
    const float cosTheta = std::fmin(1.0f, std::fmax(0.0f, float(dot(a.rotation, target))));
    if (cosTheta >= 0.9995f) {
        ret.rotation = lerp(a.rotation, target, weight);
    }
    else {
        const float theta = std::acos(cosTheta);
        const float invSinTheta = 1.0f / std::sin(theta);
        const float previousFactor = std::sin((1.0f - weight) * theta) * invSinTheta;
        const float currentFactor = std::sin(weight * theta) * invSinTheta;
        ret.rotation = a.rotation * previousFactor + target * currentFactor;
    }
}
else if (float(dot(a.rotation, b.rotation)) > 0.0f) {
    ret.rotation = lerp(a.rotation, b.rotation, weight);
}
else {
    ret.rotation = lerp(a.rotation, -b.rotation, weight);
}
